const READER = {"type": "object", "properties": {"cell": {"type": "string"}, "items": {"type": "array", "items": {"type": "object", "properties": {"id": {"type": "string"}, "verdict": {"type": "string", "enum": ["yes", "no"]}, "evidence": {"type": "string"}}, "required": ["id", "verdict", "evidence"]}}, "yes": {"type": "integer"}, "ranking": {"type": "array", "items": {"type": "string"}}, "rankingReason": {"type": "string"}}, "required": ["cell", "items", "yes", "ranking", "rankingReason"]}

const fill = (t, label) => t.split('{{LABEL}}').join(label)
const previousList = (labels) => labels.length
